fn one_point_grid() {
    let est = MusicEstimator3d {
        azimuth_steps: 1,
        azimuth_interval: (0.0, PI),
        elevation_steps: 1,
        elevation_interval: (0.0, 0.2),
        ..MusicEstimator3d::new(tetrahedron(), SAMPLE_RATE)
