    let data = plane_wave_real(&tetrahedron(), source, 1000.0, SAMPLE_RATE, 4000);
    for amplitude in [1e300, 1e-300] {
        let found = est.estimate_doa_from_real(&(&data * amplitude), 1, 1000.0).unwrap();
        assert_directions(&found, &[source], 1.0);
    }
}

