            elevation_interval: interval,
            ..tetrahedron()
        }
        .estimate_doa_from_real(&data, 1, 1000.0)
    };

    for (steps, interval) in [
        (0, (0.0, 2.0 * PI)),
        (360, (0.0, 2.0 * PI + 0.01)),
        (360, (-PI, 3.0 * PI)),
        (360, (1.0, 1.0)),
        (360, (2.0, 1.0)),
        (360, (f64::NAN, 1.0)),
        (360, (0.0, f64::INFINITY)),
        (360, (f64::NEG_INFINITY, 0.0)),
    ] {
        assert_eq!(
            azimuth(steps, interval),
            Err(MusicError::InvalidAngleGrid {
                angle_steps_num: steps,
                search_interval: interval
            }),
            "azimuth {steps} over {interval:?}"
