        let s = spectrum(&[&[3.0, 1.0, 0.0, 0.0, 1.0, 2.0]]);
        // On the circle, 2.0 at the last azimuth is next to 3.0 at the first: one peak
        assert_eq!(peaks(&s, 5, true), vec![(0.0, 0.0)]);
