        assert_eq!(peaks(&s, 5, true), vec![(5.5, 0.0)]);
        // Three equal points across the seam: the middle one, the first azimuth
        let s = spectrum(&[&[4.0, 4.0, 0.0, 0.0, 1.0, 4.0]]);
        assert_eq!(peaks(&s, 5, true), vec![(0.0, 0.0)]);
