        for circular in [false, true] {
            let one_d = crate::music::find_peaks(&scores, &angles, 8, circular);
            let two_d: Vec<f64> = find_peaks_2d(&s, (0.0, 4.0), 8, circular)
                .iter()
                .map(|d| d.azimuth)
                .collect();
            assert_eq!(two_d, one_d, "circular {circular}");
        }
    }
}
