    fn spectrum(rows: &[&[f64]]) -> Spectrum3d {
        let (n_el, n_az) = (rows.len(), rows[0].len());
        Spectrum3d {
            values: DMatrix::from_fn(n_el, n_az, |i, j| rows[i][j]),
