        .spectrum(&est.noise_subspace(&cov, 2).unwrap(), 1200.0)
        .unwrap();
    assert_eq!(
        est.find_peaks(&spectrum, 2),
        est.estimate_doa(&data, 2, 1200.0).unwrap()
    );
}
